static uint16_t get16(const uint8_t* ds, uint16_t at) {
  return (uint16_t)(ds[at] | ds[(uint16_t)(at + 1)] << 8);
}
static void put16(uint8_t* ds, uint16_t at, uint16_t value) {
  ds[at]                 = (uint8_t)value;
  ds[(uint16_t)(at + 1)] = (uint8_t)(value >> 8);
}
#define EVENT(kind, ...)                       \
  event(ds, kind, (uint16_t[]){ __VA_ARGS__ }, \
        (uint16_t)(sizeof((uint16_t[]){ __VA_ARGS__ }) / sizeof(uint16_t)))
#define WINDOW_PTR uint16_t
#define SAVE_PTR   uint16_t
