#define WIN_X(w)         get16(ds, w)
#define WIN_Y(w)         get16(ds, (uint16_t)((w) + 2))
#define WIN_COLUMN(w)    ds[get16(ds, (uint16_t)((w) + 8))]
#define TOP              ds[0xe2f1]
#define SAVE_AT(i)       ((uint16_t)(0xd006 + (i) * 12))
#define SAVE_SCENARIO(p) ds[p]
#define SAVE_LEVEL(p)    ds[(uint16_t)((p) + 1)]
#define SAVE_YEAR(p)     ds[(uint16_t)((p) + 2)]
#define SAVE_MONTH(p)    ds[(uint16_t)((p) + 3)]
#define SAVE_DAY(p)      ds[(uint16_t)((p) + 4)]
