#define SET_LEVEL(s) put16(ds, 0xc746, s)
#define MAP_NAME     get16(ds, 0xc744)
#define LEVEL_NAME   get16(ds, 0xc746)
#define COLUMNS(c, first, r, second, third)                                   \
  (EVENT(0, c, r, scratch, (uint16_t)(scratch + 1), (uint16_t)(scratch + 2)), \
   first = ds[scratch], second = ds[(uint16_t)(scratch + 1)],                 \
   third = ds[(uint16_t)(scratch + 2)])
#define POSITION(x, y)             EVENT(1, (uint16_t)(x), (uint16_t)(y))
#define FORMAT(...)                EVENT(2, __VA_ARGS__)
#define PRINT(...)                 EVENT(6, __VA_ARGS__)
#define PUT_RANGE(p, start, count) EVENT(7, p, start, count)
#define SAVE_HEADER                0x5acf
#define SAVE_NUMBER                0x5b05
#define MAP_FRANCE                 0x5b0c
#define MAP_AFRICA                 0x5b13
#define MAP_KURSK                  0x5b1a
#define MAP_DDAY                   0x5b21
#define MAP_BULGE                  0x5b28
#define MAP_BERLIN                 0x5b2f
#define LEVEL_VEASY                0x5b36
#define LEVEL_EASY                 0x5b3d
#define LEVEL_AVG                  0x5b44
#define LEVEL_HARD                 0x5b4b
#define LEVEL_VHARD                0x5b52
#define SAVE_ROW                   0x5b59

/* Choice callback: always accepts. */
uint8_t opeu_tbl_save_accept(void) {
  return 1;
}

/* Saved-game table: slot number, scenario, difficulty, date and players. */
void opeu_tbl_draw_saves(uint8_t ds[65536], HostEvent event, uint16_t scratch,
                         uint8_t column, uint8_t first, uint8_t row,
                         uint8_t last, uint8_t flags) {
  uint8_t    a, b, c, d;
  SAVE_PTR   e;
  WINDOW_PTR f;
  BUFFER(g, 100, 4);
  f = WINDOW;
  COLUMNS(column, c, row, b, a);
  if (flags & 3) {
    FORMAT(g, SAVE_HEADER);
    POSITION(WIN_COLUMN(f) + c + WIN_X(f) - 0x20, WIN_Y(f) + 1);
    PUT_RANGE(g, b, a);
  }
  for (d = first; d <= last; ++d) {
    e = SAVE_AT(d);
    if (flags & 5) {
      POSITION(WIN_X(f) + 3, (d - TOP) * 17 + WIN_Y(f) + 18);
      PRINT(SAVE_NUMBER, d + 1);
    }
    switch (SAVE_SCENARIO(e) & 0x7f) {
      case 0: SET_MAP(MAP_FRANCE); break;
      case 1: SET_MAP(MAP_AFRICA); break;
      case 2: SET_MAP(MAP_KURSK); break;
      case 3: SET_MAP(MAP_DDAY); break;
      case 4: SET_MAP(MAP_BULGE); break;
      case 5: SET_MAP(MAP_BERLIN); break;
    }
    switch (SAVE_LEVEL(e)) {
      case 0: SET_LEVEL(LEVEL_VEASY); break;
      case 1: SET_LEVEL(LEVEL_EASY); break;
      case 2: SET_LEVEL(LEVEL_AVG); break;
      case 3: SET_LEVEL(LEVEL_HARD); break;
      case 4: SET_LEVEL(LEVEL_VHARD); break;
    }
    if ((SAVE_SCENARIO(e) & 0x7f) != 6) {
      FORMAT(g, SAVE_ROW, MAP_NAME, LEVEL_NAME, SAVE_MONTH(e), SAVE_DAY(e),
             SAVE_YEAR(e), SAVE_HOUR(e), PLAYER(e, 0), PLAYER(e, 1));
      POSITION(WIN_COLUMN(f) + c + WIN_X(f) - 0x20,
               (d - TOP) * 17 + WIN_Y(f) + 18);
      PUT_RANGE(g, b, a);
    }
  }
}

